let table = defaultContext.getData("table");

if({{table:sqt_no_type}} !== -9999 && (
  !{{table:sqt_no}} || {{table:sqt_no}} === null || {{table:sqt_no}} === ''
)) {
  table.sqt_no = 'draft'
}

return table;

return {
  required_fields: JSON.stringify([
  { name: "sqt_plant", label: "Plant" },
  { name: "sqt_no", label: "Quotation Number" },
  {
    name: "table_sqt",
    label: "Item Information",
    isArray: true,
    arrayType: "object",
    arrayFields: [],
  },
]),
  data: JSON.stringify({
    sqt_plant: {{table:sqt_plant}},
    sqt_no: {{table:sqt_no}},
    table_sqt: {{table:table_sqt}}
  })
}

let table = defaultContext.getData("table");

// SQT_SAVE already marks new and Draft -> Issued saves; never renumber a quotation that has a number.
if (
  {{table:sqt_no_type}} !== -9999 &&
  (!{{table:sqt_no}} ||
    {{table:sqt_no}} === null ||
    {{table:sqt_no}} === "")
) {
  table.sqt_no = 'issued'
}

if(!{{table:need_cl}} || {{table:need_cl}} === '' || {{table:need_cl}} === null) {
  if({{table:customer_type}} === 'Existing Customer' && {{table:acc_integration_type}} !== 'No Accounting') {
    table.need_cl = 'required'
  } else {
    table.need_cl = 'not required'
  }
}

return table;

return {
  required_fields: JSON.stringify([
  { name: "sqt_plant", label: "Plant" },
  { name: "sqt_date", label: "Quotation Date" },
  { name: "sqt_no", label: "Quotation Number" },
  {
    name: "table_sqt",
    label: "Item Information",
    isArray: true,
    arrayType: "object",
    arrayFields: [],
  },
]),
  data: JSON.stringify({
    sqt_plant: {{table:sqt_plant}},
    sqt_date: {{table:sqt_date}},
    sqt_no: {{table:sqt_no}},
    table_sqt: {{table:table_sqt}}
  })
}

let table = defaultContext.getData("table");

let table_sqt = {{table:table_sqt}}.filter(item => (item.material_id || item.sqt_desc || item.material_name) && item.quantity > 0)

defaultContext.setNestedData("table.table_sqt", table_sqt);
return table;

const message = {{node:workflow_node_ImCTgGvI.data.message}};

const isBlock = message.indexOf('Block - ') !== -1 ? 'block' : 'override';

return {
  isBlock
}

let updatedLineItem = [];
let customerName = "";

if ({{table:customer_type}} === "Existing Customer") {
  customerName = {{node:get_node_RCT8cRl3.data.data.customer_com_name}}
} else {
  customerName = {{node:code_node_FFVsIuU1.data.customer_name}}
}

for(const [index, sqtLineItem] of {{table:table_sqt}}.entries()) {
  // Create a new object with formatted values
  const formattedItem = {
    // Copy all existing properties
    ...sqtLineItem,

    // Apply number formatting to numeric fields
    quantity: parseFloat(sqtLineItem.quantity?.toFixed(3)) || 0,
    unit_price: parseFloat(sqtLineItem.unit_price?.toFixed(4)) || 0,
    sqt_gross: parseFloat(sqtLineItem.sqt_gross?.toFixed(4)) || 0,
    sqt_discount: parseFloat(sqtLineItem.sqt_discount?.toFixed(4)) || 0,
    sqt_discount_amount: parseFloat(sqtLineItem.sqt_discount_amount?.toFixed(4)) || 0,
    sqt_taxes_fee_amount: parseFloat(sqtLineItem.sqt_taxes_fee_amount?.toFixed(4)) || 0,
    total_price: parseFloat(sqtLineItem.total_price?.toFixed(4)) || 0,

    // Override with new field assignments
    customer_id: {{table:sqt_customer_id}} || null,
    plant_id: {{table:sqt_plant}} || null,
    payment_term_id: {{table:sqt_payment_term}} || null,
    sales_person_id: {{table:sales_person_id}} || null,
    area_id: {{table:sqt_area_id}} || null,
    billing_state_id: {{table:billing_address_state}} || null,
    billing_country_id: {{table:billing_address_country}} || null,
    shipping_state_id: {{table:shipping_address_state}} || null,
    shipping_country_id: {{table:shipping_address_country}} || null,
    customer_name: customerName,
    line_index: index + 1,
    organization_id: {{table:organization_id}},
    access_group: {{table:access_group}} || [],
    agent_user_id: {{table:agent_user_id}} || null,
    expected_shipment_date: sqtLineItem.expected_shipment_date ? sqtLineItem.expected_shipment_date : {{table:expected_shipment_date}}
  };

  updatedLineItem.push(formattedItem);
}

let table = defaultContext.getData("table");
table.need_cl = '';
defaultContext.setNestedData("table.table_sqt", updatedLineItem);
return table;

const lineItem = {{table:table_sqt}};

const uniqueItemIDs = [
  ...new Set(lineItem.filter((item) => item.material_id).map((item) => item.material_id))
];

return {
  itemIDs: uniqueItemIDs
}
